@layer hj.components {
  /* Customise: --hj-kbd-height · --hj-kbd-bg */
  .hj-kbd {
    --_h: var(--hj-kbd-height, 22px);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: var(--_h);
    height: var(--_h);
    padding: 0 calc(6px * var(--hj-density));
    border-radius: 6px;
    background: var(--hj-kbd-bg, var(--hj-surface-2));
    box-shadow:
      inset 0 0 0 1px var(--hj-line),
      inset 0 -1px 0 var(--hj-line);
    color: var(--hj-fg-dim);
    font: 500 12px / 1 var(--hj-font-mono);
    letter-spacing: 0;
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
    vertical-align: baseline;
  }
  .hj-kbd[data-size='sm'] {
    --_h: var(--hj-kbd-height, 18px);
    padding: 0 calc(4px * var(--hj-density));
    border-radius: 5px;
    font-size: 10.5px;
  }
  .hj-kbd + .hj-kbd {
    margin-left: calc(3px * var(--hj-density));
  }
}

'use client';
import { useRender } from '@base-ui/react/use-render';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { cls, withDefaults } from '../../system/slot.ts';

/** Props hanji adds to `<kbd>`. */
export interface KbdOwnProps {
  /** sm 18 tall (inside fields and menus) · md 22 (in prose). */
  size?: 'sm' | 'md';
  render?: useRender.RenderProp;
}

export interface KbdProps extends KbdOwnProps, Omit<React.ComponentProps<'kbd'>, 'className'> {
  className?: string;
}

/**
 * A key on the keyboard, set in mono on a hairline. Combine keys by placing several side by side.
 *
 * @example
 * <Kbd>⌘</Kbd><Kbd>K</Kbd>
 */
export function Kbd(props: KbdProps): React.ReactElement {
  const config = useHanjiConfig();
  const { size = 'md', render, className, ...rest } = withDefaults(config, 'Kbd', props);
  return useRender({
    render,
    defaultTagName: 'kbd',
    props: {
      ...rest,
      'data-size': size,
      className: cls(config, 'Kbd', 'hj-kbd', className) as string | undefined,
    },
  });
}
